def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find rows/columns that form the lattice separators: their cells are
    # mostly the separator color, with occasional marker colors.
    def separator_rows():
        out = []
        for r, row in enumerate(grid):
            if len(set(row)) <= 3 and max(row.count(v) for v in set(row)) >= w - 2:
                out.append(r)
        return out

    def separator_cols():
        out = []
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) <= 3 and max(vals.count(v) for v in set(vals)) >= h - 2:
                out.append(c)
        return out

    rs, cs = separator_rows(), separator_cols()

    # Reduce each lattice tile to the color at its upper-left separator
    # crossing. The last separator is the outer boundary, not a tile start.
    if len(rs) >= 2 and len(cs) >= 2:
        return [[grid[rs[i]][cs[j]] for j in range(len(cs) - 1)]
                for i in range(len(rs) - 1)]

    return [[grid[0][0]]]
